{
  "name": "patch-for-omo",
  "version": "1.0.2",
  "description": "Enhancement plugin for Oh My OpenCode - Adds Receptionist and Secretary agents for cost optimization and workflow management",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "bin": {
    "patch-for-omo": "./dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "jest",
    "test:coverage": "jest --coverage",
    "lint": "eslint src/**/*.ts",
    "format": "prettier --write src/**/*.ts",
    "prepare": "npm run build",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "oh-my-opencode",
    "plugin",
    "ai-agent",
    "cost-optimization",
    "workflow-management",
    "multi-agent"
  ],
  "author": "huajianjiu",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/huajianjiu/patch-for-omo.git"
  },
  "bugs": {
    "url": "https://github.com/huajianjiu/patch-for-omo/issues"
  },
  "homepage": "https://github.com/huajianjiu/patch-for-omo#readme",
  "engines": {
    "node": ">=16.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0",
    "oh-my-opencode": ">=1.0.0"
  },
  "devDependencies": {
    "@types/jest": "^29.5.0",
    "@types/node": "^20.0.0",
    "@typescript-eslint/eslint-plugin": "^6.0.0",
    "@typescript-eslint/parser": "^6.0.0",
    "eslint": "^8.0.0",
    "jest": "^29.5.0",
    "prettier": "^3.0.0",
    "ts-jest": "^29.1.0",
    "typescript": "^5.0.0"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@opencode-ai/sdk": "^1.0.0",
    "zod": "^3.22.0"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ]
}
